const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;min-width:0;min-height:0;display:flex;flex-direction:column;overflow:hidden;background:transparent;color:var(--ink);font-family:system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;font-size:13px;line-height:1.4}\n.card *{box-sizing:border-box}\n.app{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;padding:10px}\n.page{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px}\nbutton{font:inherit}\n\n.btn{flex:none;height:28px;padding:0 10px;border-radius:8px;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);font-size:12px;white-space:nowrap;cursor:pointer}\n.btn:disabled{opacity:.5;cursor:default}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:650}\n.btn.pk{border-color:var(--accent);color:var(--ink)}\n.btn.sel{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:650}\n.btn.ghost{background:transparent;color:var(--muted)}\n.btn.sq{width:28px;padding:0;font-size:16px;line-height:1}\n.btn.sm{height:26px;padding:0 8px}\n.btn.add{min-width:28px}\n.btn:focus-visible,.chip:focus-visible,.vname:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n\n.top{display:flex;align-items:center;gap:6px;flex:none;min-width:0}\n.vname{flex:1 1 0;min-width:0;height:28px;display:flex;align-items:center;gap:4px;padding:0 2px;border:0;background:none;color:var(--ink);font-size:15px;font-weight:700;text-align:left;cursor:pointer}\n.vn{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.car{flex:none;color:var(--muted);font-size:11px}\n.meta{flex:none;font-size:11px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.meta.inl{flex:0 1 auto}\n.msg,.err{flex:none;padding:4px 8px;border-radius:8px;border:1px solid var(--line);background:var(--soft);font-size:11.5px;word-break:break-word}\n.err{display:none}\n.err.show{display:block}\n\n.cov{position:relative;flex:none;display:flex;align-items:center;justify-content:center;aspect-ratio:16/9;padding:20px 10px 10px;border-radius:8px;border:1px solid var(--line);overflow:hidden;text-align:center;background:linear-gradient(135deg,var(--soft),var(--panel-paper))}\n.cov::before{content:\"\";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--accent)}\n.cov::after{content:\"\u25b6\";position:absolute;right:7px;bottom:4px;font-size:9px;color:var(--muted)}\n.covt{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:3;overflow:hidden;max-width:100%;font-weight:800;line-height:1.18;word-break:break-all}\n.k1 .covt{font-size:26px}\n.k2 .covt{font-size:19px}\n.k3 .covt{font-size:15px}\n.k4 .covt{font-size:12.5px;font-weight:700}\n.k0 .covt{font-size:11px;font-weight:400;color:var(--muted)}\n.pill{position:absolute;left:8px;top:5px;max-width:58%;padding:0 6px;border-radius:99px;border:1px solid var(--line);background:var(--panel-paper);font-size:10px;font-weight:700;line-height:15px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.flag{position:absolute;right:5px;top:5px;padding:0 7px;border-radius:99px;background:var(--accent);color:var(--on-accent);font-size:10px;font-weight:700;line-height:15px;white-space:nowrap}\n\n.sc{display:flex;flex-direction:column;gap:6px;min-width:0;padding:8px;border-radius:12px;border:1px solid var(--line);background:var(--panel-paper)}\n.sc.on{border-color:var(--accent);box-shadow:inset 0 0 0 1px var(--accent)}\n.sc-body,.one,.vmain{outline:none;cursor:pointer;min-width:0}\n.sc-body:focus-visible,.one:focus-visible,.vmain:focus-visible{outline:2px solid var(--accent);outline-offset:2px;border-radius:8px}\n.sc-body{display:flex;flex-direction:column;gap:5px;flex:1;min-height:0}\n.ti{font-size:13px;font-weight:650;line-height:1.3;word-break:break-word;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:3;overflow:hidden}\n.ti.none,.vi.none{color:var(--muted);font-weight:400}\n.cnt{margin-left:5px;font-size:10.5px;font-weight:400;color:var(--muted);white-space:nowrap}\n.vi{font-size:11.5px;color:var(--muted);line-height:1.35;word-break:break-word;white-space:pre-wrap;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:3;overflow:hidden}\n.vi b{margin-right:5px;padding:0 4px;border-radius:4px;background:var(--soft);color:var(--ink);font-size:10px;font-weight:700}\n.sc-ft{display:flex;gap:6px;flex:none}\n.sc-ft .btn{flex:1;min-width:0;padding:0 6px}\n\n.vlist{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:8px;overflow-y:auto;scrollbar-width:thin}\n.vlist .sc{flex:0 0 auto}\n.hlist{flex:1;min-height:0;min-width:0;display:flex;gap:8px;overflow-x:auto;overflow-y:hidden;scrollbar-width:thin}\n.grid{flex:1;min-height:0;min-width:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;align-content:start;overflow-y:auto;scrollbar-width:thin}\n\n.chips{display:flex;gap:6px;flex:none;overflow-x:auto;scrollbar-width:thin;padding-bottom:3px}\n.chip{flex:0 0 auto;max-width:150px;height:26px;padding:0 10px;border-radius:99px;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;cursor:pointer}\n.chip.on{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:650}\n.chip.add,.chip.all{color:var(--muted);border-style:dashed}\n\n.bar{display:flex;align-items:center;gap:6px;flex:none;min-width:0}\n.bt{flex:1;min-width:0;font-size:14px;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.scroll{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:8px;overflow-y:auto;scrollbar-width:thin}\n.scroll.rows{gap:6px}\n\n.vrow{flex:none;display:flex;align-items:center;gap:6px;padding:7px 8px 7px 10px;border-radius:10px;border:1px solid var(--line);background:var(--panel-paper)}\n.vrow.cur{border-color:var(--accent);box-shadow:inset 0 0 0 1px var(--accent)}\n.vmain{flex:1;min-width:0}\n.vt{font-weight:650;font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.vm{font-size:11px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n\n.empty{flex:1;min-height:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;padding:6px;text-align:center}\n.ei{width:46px;height:30px;display:grid;place-items:center;border-radius:8px;border:1px solid var(--line);background:var(--soft);font-size:13px}\n.et{font-size:14px;font-weight:700}\n.eh{max-width:270px;font-size:12px;color:var(--muted)}\n\n.fbody{gap:8px}\n.fgrid{display:grid;grid-template-columns:minmax(0,1fr);gap:8px}\n.fld{display:flex;flex-direction:column;gap:3px;min-width:0}\n.lab{display:flex;justify-content:space-between;gap:6px;font-size:11px;color:var(--muted)}\n.cn{font-weight:400;white-space:nowrap}\n.inp{display:block;width:100%;min-width:0;padding:6px 8px;border-radius:8px;border:1px solid var(--line);background:var(--paper);color:var(--ink);font:inherit;font-size:13px;line-height:1.35}\ntextarea.inp{resize:vertical;min-height:34px}\n.inp:focus{outline:2px solid var(--accent);outline-offset:0}\n.inp::placeholder{color:var(--muted);opacity:.8}\n\n.det{gap:9px}\n.dl{display:flex;flex-direction:column;gap:2px;min-width:0}\n.dk{display:flex;justify-content:space-between;font-size:11px;color:var(--muted)}\n.dv{font-size:13.5px;line-height:1.45;white-space:pre-wrap;word-break:break-word}\n.dv.none{color:var(--muted)}\n.acts{display:flex;flex-wrap:wrap;gap:6px;padding-top:2px}\n.warn{flex:1 0 100%;font-size:11.5px;line-height:1.4}\n\n.card[data-size=\"3x3\"] .app{padding:8px}\n.card[data-size=\"3x3\"] .page{gap:6px}\n.card[data-size=\"3x3\"] .vname{font-size:13px}\n.card[data-size=\"3x3\"] .cov{aspect-ratio:auto;height:64px;padding:17px 8px 6px}\n.card[data-size=\"3x3\"] .k1 .covt{font-size:22px}\n.card[data-size=\"3x3\"] .k2 .covt{font-size:16px}\n.card[data-size=\"3x3\"] .k3 .covt{font-size:13px}\n.card[data-size=\"3x3\"] .k4 .covt{font-size:11px}\n.card[data-size=\"3x3\"] .covt{-webkit-line-clamp:2}\n.card[data-size=\"3x3\"] .one{flex:1;min-height:0;display:flex;flex-direction:column;gap:5px;overflow:hidden}\n.card[data-size=\"3x3\"] .one .ti{font-size:12.5px;-webkit-line-clamp:2}\n.card[data-size=\"3x3\"] .pager{flex:none;display:flex;align-items:center;gap:4px}\n.card[data-size=\"3x3\"] .pg{min-width:32px;text-align:center;font-size:11px;color:var(--muted)}\n.card[data-size=\"3x3\"] .sp{flex:1}\n.card[data-size=\"3x3\"] .cnt,.card[data-size=\"6x3\"] .cnt{display:none}\n.card[data-size=\"3x3\"] .empty{gap:6px}\n.card[data-size=\"3x3\"] .ei{width:38px;height:26px}\n.card[data-size=\"3x3\"] .et{font-size:13px}\n.card[data-size=\"3x3\"] .det .cov,.card[data-size=\"6x3\"] .det .cov{flex:none}\n\n.card[data-size=\"6x3\"] .app{padding:8px}\n.card[data-size=\"6x3\"] .page{gap:6px}\n.card[data-size=\"6x3\"] .sc{flex:0 0 158px;gap:4px;padding:6px;border-radius:10px}\n.card[data-size=\"6x3\"] .sc-body{gap:4px;overflow:hidden}\n.card[data-size=\"6x3\"] .cov{aspect-ratio:auto;height:46px;padding:15px 6px 3px}\n.card[data-size=\"6x3\"] .k1 .covt{font-size:18px}\n.card[data-size=\"6x3\"] .k2 .covt{font-size:14px}\n.card[data-size=\"6x3\"] .k3 .covt{font-size:12px}\n.card[data-size=\"6x3\"] .k4 .covt{font-size:11px}\n.card[data-size=\"6x3\"] .covt{-webkit-line-clamp:2}\n.card[data-size=\"6x3\"] .ti{font-size:12px;line-height:1.25;-webkit-line-clamp:2}\n.card[data-size=\"6x3\"] .vi{font-size:11px;-webkit-line-clamp:1}\n.card[data-size=\"6x3\"] .sc-ft .btn{height:24px;font-size:11px}\n.card[data-size=\"6x3\"] .fgrid,.card[data-size=\"6x6\"] .fgrid{grid-template-columns:repeat(2,minmax(0,1fr))}\n.card[data-size=\"6x3\"] .f-visual,.card[data-size=\"6x6\"] .f-visual{grid-column:1/-1}\n\n.card[data-size=\"3x6\"] .app{padding:9px}\n.card[data-size=\"6x6\"] .app{padding:10px}\n.card[data-size=\"6x6\"] .page{gap:7px}\n";
var LETTERS='ABCDEFGHIJKLMNOPQRSTUVWXYZ';
function tagOf(sc,i){var n=sc&&sc.no?sc.no:(i+1);return n>=1&&n<=26?LETTERS.charAt(n-1):String(n);}
function clen(t){return Array.from(String(t==null?'':t)).length;}
function tr(t){return String(t==null?'':t).trim();}
function oneLine(t){return tr(t).replace(/\s*[\r\n]+\s*/g,' ');}
function listOf(v){return v&&Array.isArray(v.schemes)?v.schemes:[];}
function isEnter(e){return e.key==='Enter'&&!e.isComposing&&e.keyCode!==229;}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day}=ctx;
  const sz=ctx.size||root.getAttribute('data-size')||'6x6';
  const videos=state&&Array.isArray(state.videos)?state.videos:[];
  const cur=videos.find(v=>v.id===ui.vid)||videos[0]||null;
  const schemes=listOf(cur);
  const pickedSc=cur?(schemes.find(x=>x.id===cur.pickedId)||null):null;
  const curSc=ui.sid?(schemes.find(x=>x.id===ui.sid)||null):null;
  const editSc=ui.editId?(schemes.find(x=>x.id===ui.editId)||null):null;
  let view=ui.view||'main';
  if((view==='sform'||view==='detail')&&!cur)view='main';
  if(view==='detail'&&!curSc)view='main';
  if(view==='sform'&&ui.editId&&!editSc)view='main';
  if(view==='vform'&&ui.editVid&&!videos.some(v=>v.id===ui.editVid))view='main';
  let saving=false;
  let errEl=null;
  const scrollers=[];
  let chipsEl=null;

  function h(tag,attrs,...kids){
    const flat=kids.flat(2).filter(k=>k!==null&&k!==undefined&&k!==false);
    return el(tag,attrs||{},...flat);
  }
  function btn(label,onclick,cls){return h('button',{type:'button',class:'btn '+(cls||''),onclick:onclick},label);}
  function go(patch){
    ui.msg='';ui.confirm=null;ui.sT=0;ui.sL=0;
    Object.assign(ui,patch);
    redraw();
  }
  function nu(patch){
    return Object.assign({view:'main',vid:cur?cur.id:null,sid:ui.sid||null,draft:null,editId:null,editVid:null,from:'main',msg:'',confirm:null,sT:0,sL:0,cL:ui.cL||0},patch);
  }
  function fail(e){ui.msg='保存失败：'+((e&&e.message)||'请稍后重试');redraw();}
  function mapV(s,id,fn){
    const l=s&&Array.isArray(s.videos)?s.videos:[];
    return Object.assign({},s,{videos:l.map(x=>x.id===id?fn(x):x)});
  }
  function track(box){
    box.addEventListener('scroll',()=>{ui.sT=box.scrollTop;ui.sL=box.scrollLeft;});
    scrollers.push(box);
    return box;
  }
  function showErr(t){if(errEl){errEl.textContent='! '+t;errEl.classList.add('show');}}


  function doPick(sc){
    const vid=cur.id;
    update(s=>mapV(s,vid,v=>Object.assign({},v,{pickedId:v.pickedId===sc.id?null:sc.id}))).catch(fail);
  }
  function blankDraft(){return {label:'',title:'',cover:'',visual:''};}
  function openAdd(){go({view:'sform',draft:blankDraft(),editId:null,from:'main'});}
  function openEdit(sc,from){
    go({view:'sform',draft:{label:sc.label||'',title:sc.title||'',cover:sc.cover||'',visual:sc.visual||''},editId:sc.id,sid:sc.id,from:from||'main'});
  }
  function openCopy(sc){
    go({view:'sform',draft:{label:sc.label?sc.label+'·副本':'',title:sc.title||'',cover:sc.cover||'',visual:sc.visual||''},editId:null,from:'detail'});
  }
  function openVForm(id,name){go({view:'vform',editVid:id,draft:{name:name||''},from:view});}

  function saveScheme(sb){
    if(saving)return;
    const d=ui.draft||{};
    const t=oneLine(d.title),c=oneLine(d.cover),vi=tr(d.visual),lb=oneLine(d.label);
    if(!t&&!c&&!vi){showErr('标题、封面短句、画面想法至少填写一项');return;}
    saving=true;if(sb)sb.disabled=true;
    const vid=cur.id,editId=ui.editId,id=editId||uid(),from=ui.from;
    const fields={label:lb,title:t,cover:c,visual:vi};
    const back=(editId&&from==='detail')?'detail':'main';
    commit(s=>mapV(s,vid,v=>{
      const l=listOf(v);
      if(editId)return Object.assign({},v,{schemes:l.map(x=>x.id===editId?Object.assign({},x,fields):x)});
      const mx=l.reduce((m,x)=>Math.max(m,x.no||0),0);
      const no=Math.max(v.seq||0,mx)+1;
      return Object.assign({},v,{seq:no,schemes:l.concat([Object.assign({id:id,no:no,at:day()},fields)])});
    }),nu({view:back,sid:id})).then(ok=>{
      if(ok===false){saving=false;if(sb)sb.disabled=false;showErr('保存没有成功，请重试');}
    }).catch(e=>{
      saving=false;if(sb)sb.disabled=false;showErr('保存失败：'+((e&&e.message)||'请重试'));
    });
  }
  function saveVideo(sb){
    if(saving)return;
    const name=oneLine((ui.draft||{}).name);
    if(!name){showErr('请填写视频名称');return;}
    saving=true;if(sb)sb.disabled=true;
    const editVid=ui.editVid,id=editVid||uid(),from=ui.from;
    const target=editVid?(from==='videos'?'videos':'main'):'main';
    commit(s=>{
      const l=s&&Array.isArray(s.videos)?s.videos:[];
      if(editVid)return Object.assign({},s,{videos:l.map(v=>v.id===editVid?Object.assign({},v,{name:name}):v)});
      return Object.assign({},s,{videos:l.concat([{id:id,name:name,pickedId:null,seq:0,schemes:[],at:day()}])});
    },nu({view:target,vid:editVid?(cur?cur.id:null):id,sid:null,editVid:null})).then(ok=>{
      if(ok===false){saving=false;if(sb)sb.disabled=false;showErr('保存没有成功，请重试');}
    }).catch(e=>{
      saving=false;if(sb)sb.disabled=false;showErr('保存失败：'+((e&&e.message)||'请重试'));
    });
  }
  function delScheme(sc){
    const vid=cur.id;
    commit(s=>mapV(s,vid,v=>Object.assign({},v,{pickedId:v.pickedId===sc.id?null:v.pickedId,schemes:listOf(v).filter(x=>x.id!==sc.id)})),nu({view:'main',sid:null})).catch(fail);
  }
  function delVideo(){
    const id=ui.editVid;
    commit(s=>{
      const l=s&&Array.isArray(s.videos)?s.videos:[];
      return Object.assign({},s,{videos:l.filter(v=>v.id!==id)});
    },nu({view:videos.length>1?'videos':'main',vid:null,sid:null,editVid:null})).catch(fail);
  }

  function metaText(){
    const n=schemes.length;
    if(!n)return '暂无方案';
    return n+' 套方案 · '+(pickedSc?'已选 '+tagOf(pickedSc,schemes.indexOf(pickedSc)):'未选定');
  }
  function coverBox(sc,i,picked){
    const t=tr(sc.cover),n=clen(t);
    const k=!t?'k0':n<=4?'k1':n<=8?'k2':n<=14?'k3':'k4';
    return h('div',{class:'cov '+k},
      h('span',{class:'pill'},tagOf(sc,i)+(sc.label?' · '+sc.label:'')),
      picked?h('span',{class:'flag'},'✓ 已选用'):null,
      h('span',{class:'covt'},t||'未写封面短句'));
  }
  function card(sc,i){
    const picked=cur.pickedId===sc.id;
    const open=()=>go({view:'detail',sid:sc.id});
    const body=h('div',{class:'sc-body',role:'button',tabindex:'0',onclick:open,onkeydown:e=>{if(isEnter(e))open();}},
      coverBox(sc,i,picked),
      h('div',{class:'ti'+(sc.title?'':' none')},sc.title||'未写标题',sc.title?h('span',{class:'cnt'},clen(sc.title)+' 字'):null),
      h('div',{class:'vi'+(sc.visual?'':' none')},h('b',{},'画面'),sc.visual||'未写画面想法'));
    return h('article',{class:'sc'+(picked?' on':'')},body,
      h('div',{class:'sc-ft'},
        btn(picked?'✓ 已选':'选用',()=>doPick(sc),picked?'sel':'pk'),
        btn('编辑',()=>openEdit(sc,'main'),'')));
  }


  function bar(title,onBack,right){
    return h('div',{class:'bar'},onBack?btn('‹',onBack,'sq'):null,h('div',{class:'bt'},title),right||null);
  }
  function viewEmpty(){
    return h('section',{class:'page'},h('div',{class:'empty'},
      h('div',{class:'ei'},'▶'),
      h('div',{class:'et'},'还没有视频'),
      sz==='3x3'?null:h('div',{class:'eh'},'每条视频可存几套标题、封面短句和画面想法，并排比较后选定一套。'),
      btn('添加视频',()=>openVForm(null,''),'primary')));
  }
  function emptySchemes(){
    return h('div',{class:'empty'},
      h('div',{class:'et'},'这条视频还没有方案'),
      sz==='3x3'?null:h('div',{class:'eh'},'先写一套标题、封面短句和画面想法，之后可以再加几套来比较。'),
      btn('添加第一套方案',openAdd,'primary'));
  }
  function topbar(){
    return h('div',{class:'top'},
      h('button',{type:'button',class:'vname','aria-label':'切换视频',onclick:()=>go({view:'videos'})},
        h('span',{class:'vn'},cur.name),h('span',{class:'car'},'▾')),
      sz==='6x3'?h('span',{class:'meta inl'},metaText()):null,
      sz==='6x6'?btn('改名',()=>openVForm(cur.id,cur.name),'ghost'):null,
      btn(sz==='3x3'?'+':'+ 方案',openAdd,'primary add'));
  }
  function chips(){
    const row=h('div',{class:'chips'},
      h('button',{type:'button',class:'chip all',onclick:()=>go({view:'videos'})},'☰ 全部'),
      videos.map(v=>h('button',{type:'button',class:'chip'+(v.id===cur.id?' on':''),onclick:()=>go({vid:v.id,sid:null})},(v.pickedId?'✓ ':'')+v.name)),
      h('button',{type:'button',class:'chip add',onclick:()=>openVForm(null,'')},'+ 视频'));
