      h('div',{class:'one',role:'button',tabindex:'0',onclick:open,onkeydown:e=>{if(isEnter(e))open();}},
        coverBox(sc,i,picked),
        h('div',{class:'ti'+(sc.title?'':' none')},sc.title||'未写标题')),
      h('div',{class:'pager'},
        n>1?btn('‹',()=>step(-1),'sq'):null,
        h('span',{class:'pg'},tagOf(sc,i)+' '+(i+1)+'/'+n),
        n>1?btn('›',()=>step(1),'sq'):null,
        h('span',{class:'sp'}),
        btn(picked?'✓ 已选':'选用',()=>doPick(sc),picked?'sel':'pk'))
