  }
  function viewMain(){
    let body;
    if(!schemes.length)body=emptySchemes();
    else if(sz==='3x3')body=body33();
    else if(sz==='6x3')body=listCards('hlist');
    else if(sz==='3x6')body=listCards('vlist');
