        danger));
  }
  function dl(label,val,withCnt){
    return h('div',{class:'dl'},
      h('div',{class:'dk'},h('span',{},label),withCnt&&val?h('span',{class:'cn'},clen(val)+' 字'):null),
      h('div',{class:'dv'+(val?'':' none')},val||'未填写'));
  }
  function viewDetail(){
    const sc=curSc,i=schemes.indexOf(sc),picked=cur.pickedId===sc.id;
    const acts=ui.confirm==='sc'
      ?h('div',{class:'acts'},
          h('div',{class:'warn'},'! 删除后无法恢复。只想先放一边的话，保留它即可，不用删除。'),
