          btn('复制为新方案',()=>openCopy(sc),''),
          btn('删除',()=>{ui.confirm='sc';redraw();},'ghost'));
    return h('section',{class:'page'},
      bar(tagOf(sc,i)+(sc.label?' · '+sc.label:' 方案'),()=>go({view:'main'}),
        btn(picked?'✓ 已选用':'选用',()=>doPick(sc),picked?'sel':'pk')),
      track(h('div',{class:'scroll det'},
        coverBox(sc,i,picked),
        dl('标题',sc.title,true),
        dl('封面短句',sc.cover,true),
        dl('画面想法',sc.visual,false),
        acts)));
  }

  let page;
  if(view==='videos')page=viewVideos();
  else if(view==='vform')page=viewVForm();
  else if(view==='sform')page=viewSForm();
  else if(view==='detail')page=viewDetail();
  else page=cur?viewMain():viewEmpty();

  root.appendChild(h('div',{class:'app'},page));
  function restore(){
    scrollers.forEach(b=>{b.scrollTop=ui.sT||0;b.scrollLeft=ui.sL||0;});
    if(chipsEl)chipsEl.scrollLeft=ui.cL||0;
  }
  restore();
  const tm=setTimeout(restore,30);
  return ()=>clearTimeout(tm);
}

